package com.digipals.wms.finance.entity; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="treasury_instruments") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class TreasuryInstrument { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; String instrumentNumber; String instrumentType; String counterparty; String currency; BigDecimal notionalAmount; LocalDate tradeDate; LocalDate maturityDate; String status; BigDecimal valuationAmount; boolean hedgeDesignated; }